85    class SimpleSelector : public Selector {
    86    public:
    87      enum Simple_Type {
    88        ID_SEL,
    89        TYPE_SEL,
    90        CLASS_SEL,
    91        PSEUDO_SEL,
    92        ATTRIBUTE_SEL,
    93        PLACEHOLDER_SEL,
    94      };
    95    public:
    96      HASH_CONSTREF(std::string, ns)
    97      HASH_CONSTREF(std::string, name)
    98      ADD_PROPERTY(Simple_Type, simple_type)
    99      HASH_PROPERTY(bool, has_ns)
   100    public:
   101      SimpleSelector(ParserState pstate, std::string n = "");
   102      virtual std::string ns_name() const;
   103      size_t hash() const override;
   104      virtual bool empty() const;
   105      // namespace compare functions
   106      bool is_ns_eq(const SimpleSelector& r) const;
   107      // namespace query functions
   108      bool is_universal_ns() const;
   109      bool is_empty_ns() const;
   110      bool has_empty_ns() const;
   111      bool has_qualified_ns() const;
   112      // name query functions
   113      bool is_universal() const;
   114      virtual bool has_placeholder();
   115
   116      virtual ~SimpleSelector() = 0;
   117      virtual CompoundSelector* unifyWith(CompoundSelector*);
   118
   119      /* helper function for syntax sugar */
   120      virtual Id_Selector* getIdSelector() { return NULL; }
   121      virtual Type_Selector* getTypeSelector() { return NULL; }
   122      virtual Pseudo_Selector* getPseudoSelector() { return NULL; }
   123
   124      ComplexSelectorObj wrapInComplex();
   125      CompoundSelectorObj wrapInCompound();
   126
   127      virtual bool isInvisible() const { return false; }
   128      virtual bool is_pseudo_element() const;
   129      virtual bool has_real_parent_ref() const override;
   130
   131      bool operator==(const Selector& rhs) const final override;
   132
   133      virtual bool operator==(const SelectorList& rhs) const;
   134      virtual bool operator==(const ComplexSelector& rhs) const;
   135      virtual bool operator==(const CompoundSelector& rhs) const;
   136
   137      ATTACH_VIRTUAL_CMP_OPERATIONS(SimpleSelector);
   138      ATTACH_VIRTUAL_AST_OPERATIONS(SimpleSelector);
   139      ATTACH_CRTP_PERFORM_METHODS();
   140
   141    };
   142    inline SimpleSelector::~SimpleSelector() { }
   143
